        {error && (
          <p className="text-sm text-red-600 bg-red-50 rounded-xl px-4 py-3">{error}</p>
        )}

        {/* Preview + Publish buttons */}
        <div className="flex gap-3 pt-2">
          <button
            onClick={() => setPreview(true)}
            className="flex-1 border-2 border-gray-300 text-gray-700 font-semibold py-3.5 rounded-xl text-sm"
          >
            Preview / ప్రివ్యూ
          </button>
          <button
            onClick={handlePublish}
            disabled={loading || !name.trim()}
            className="flex-1 bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm disabled:opacity-50"
          >
            {loading ? 'Publishing... / ప్రచురిస్తోంది' : 'Publish / ప్రచురించండి'}
          </button>
        </div>
      </div>

      {/* Preview modal */}
      {preview && (
        <PreviewModal data={previewData} onClose={() => setPreview(false)} />
      )}
    </div>
  )
}

/* ─── Preview modal ─────────────────────────────────────────── */
function PreviewModal({ data, onClose }: { data: PreviewData; onClose: () => void }) {
  const EMOJI_BG: Record<string, string> = {
    '🍅': 'bg-red-100', '🥬': 'bg-green-100', '🥭': 'bg-orange-100',
    '🍆': 'bg-purple-100', '🥕': 'bg-orange-100', '🌽': 'bg-yellow-100',
    '🍌': 'bg-yellow-100', '🫑': 'bg-green-100', '🌿': 'bg-green-50',
    '🌾': 'bg-amber-100', '🍓': 'bg-red-50',
  }
  const bg = EMOJI_BG[data.emoji] ?? 'bg-green-50'

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-end justify-center p-4">
      <div className="bg-white rounded-2xl w-full max-w-sm overflow-hidden">
        <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100">
          <p className="font-bold text-gray-800 text-sm">
            Preview — how buyers see this / ప్రివ్యూ
          </p>
          <button onClick={onClose} className="text-gray-400 text-2xl leading-none">×</button>
        </div>
        <div className="p-4">
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden max-w-[180px] mx-auto">
            <div className={`${bg} flex items-center justify-center py-8`}>
              <span className="text-5xl">{data.emoji}</span>
            </div>
            <div className="p-3">
              <h3 className="font-extrabold text-gray-900 text-base">{data.name}</h3>
              {data.variety && <p className="text-xs text-gray-400 mt-0.5">{data.variety}</p>}
              <div className="flex items-center justify-between mt-2">
                <span className="text-green-700 font-black text-lg">
                  {data.price !== '—' ? `₹${data.price}` : '—'}
                  <span className="text-xs font-normal text-gray-400">/kg</span>
                </span>
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-green-100 text-green-800">
                  {data.method}
                </span>
              </div>
              {data.stock !== '—' && (
                <p className="text-xs text-gray-400 mt-1">{data.stock} kg left</p>
              )}
              <div className="mt-2 w-full bg-green-700 text-white text-xs font-bold py-2.5 rounded-xl text-center">
                Order / ఆర్డర్
              </div>
            </div>
          </div>
          <p className="text-xs text-gray-400 text-center mt-3">
            This is how the card appears to buyers.<br />
            ఇది కొనుగోలుదారులకు ఎలా కనిపిస్తుందో.
          </p>
        </div>
        <div className="px-4 pb-4">
          <button
            onClick={onClose}
            className="w-full border-2 border-gray-300 text-gray-700 font-semibold py-3 rounded-xl text-sm"
          >
            Close / మూసివేయండి
          </button>
        </div>
      </div>
    </div>
  )
}

/* ─── Farm images card ──────────────────────────────────────── */
type MediaPhoto = { id: string; url: string; caption?: string | null }

function FarmImagesCard({ farmerId }: { farmerId: string }) {
  const [photos, setPhotos] = useState<MediaPhoto[]>([])
  const [loading, setLoading] = useState(true)
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState('')
  const [preview, setPreview] = useState<string | null>(null)
  const [pendingFile, setPendingFile] = useState<File | null>(null)
  const [caption, setCaption] = useState('')

  const loadPhotos = useCallback(async () => {
    setLoading(true)
    const { data } = await supabase
      .from('media')
      .select('id, url, caption')
      .eq('farmer_id', farmerId)
      .eq('type', 'photo')
      .order('sort_order', { ascending: true })
    setPhotos((data ?? []) as MediaPhoto[])
    setLoading(false)
  }, [farmerId])

  useEffect(() => { loadPhotos() }, [loadPhotos])

  const handleFile = (file: File | null) => {
    setError('')
    if (!file) return
    if (!file.type.startsWith('image/')) {
      setError('Please pick an image file / చిత్రం ఫైల్ ఎంచుకోండి')
      return
    }
    if (file.size > 8 * 1024 * 1024) {
      setError('Image is too large (max 8 MB) / చిత్రం 8 MB కంటే ఎక్కువ')
      return
    }
    setPendingFile(file)
    const reader = new FileReader()
    reader.onload = (e) => setPreview(e.target?.result as string)
    reader.readAsDataURL(file)
  }

  const handleUpload = async () => {
    if (!pendingFile) return
    setUploading(true)
    setError('')
    try {
      const ext = pendingFile.name.split('.').pop()?.toLowerCase() || 'jpg'
      const path = `${farmerId}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`
      const { error: upErr } = await supabase.storage
        .from('farm-images')
        .upload(path, pendingFile, {
          cacheControl: '3600',
          contentType: pendingFile.type,
          upsert: false,
        })
      if (upErr) throw upErr

      const { data: pub } = supabase.storage.from('farm-images').getPublicUrl(path)
      const publicUrl = pub.publicUrl

      const { error: insErr } = await supabase.from('media').insert({
        farmer_id: farmerId,
        type: 'photo',
        url: publicUrl,
        caption: caption.trim() || null,
        sort_order: photos.length,
      })
      if (insErr) throw insErr

      setPreview(null)
      setPendingFile(null)
      setCaption('')
      await loadPhotos()
    } catch (e) {
      const msg = e instanceof Error ? e.message : 'Upload failed'
      setError(msg)
    } finally {
      setUploading(false)
    }
  }

  const handleCancel = () => {
    setPreview(null)
    setPendingFile(null)
    setCaption('')
    setError('')
  }

  return (
    <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-3">
      <div>
        <h2 className="font-extrabold text-gray-900 text-base leading-tight">
          Farm photos / పొలం ఫోటోలు
        </h2>
        <p className="text-xs text-gray-500 mt-0.5">
          Show buyers your farm / కొనుగోలుదారులకు మీ పొలం చూపించండి
        </p>
      </div>

      {!preview && (
        <label className="block w-full border-2 border-dashed border-green-300 rounded-xl py-5 px-4 text-center cursor-pointer active:bg-green-50">
          <div className="text-3xl mb-1">📸</div>
          <p className="text-sm font-bold text-green-800">
            Upload photo / ఫోటో అప్‌లోడ్
          </p>
          <p className="text-[11px] text-gray-500 mt-0.5">
            Gallery or camera / గ్యాలరీ లేదా కెమెరా
          </p>
          <input
            type="file"
            accept="image/*"
            capture="environment"
            className="hidden"
            onChange={(e) => handleFile(e.target.files?.[0] ?? null)}
          />
        </label>
      )}

      {preview && (
        <div className="space-y-3">
          <div className="rounded-xl overflow-hidden bg-gray-50 border border-gray-200">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={preview} alt="Preview" className="w-full max-h-64 object-cover" />
          </div>
          <input
            type="text"
            placeholder="Caption (optional) / శీర్షిక"
            value={caption}
            onChange={(e) => setCaption(e.target.value)}
            className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
          />
          {error && (
            <p className="text-xs text-red-600 bg-red-50 rounded-lg px-3 py-2">{error}</p>
          )}
          <div className="flex gap-2">
            <button
              onClick={handleCancel}
              disabled={uploading}
              className="flex-1 border-2 border-gray-300 text-gray-700 font-semibold py-3 rounded-xl text-sm"
            >
              Cancel / రద్దు
            </button>
            <button
              onClick={handleUpload}
              disabled={uploading}
              className="flex-1 bg-green-700 text-white font-bold py-3 rounded-xl text-sm disabled:opacity-60"
            >
              {uploading ? 'Uploading... / అప్‌లోడ్' : 'Save / సేవ్'}
            </button>
          </div>
        </div>
      )}

      {!preview && error && (
        <p className="text-xs text-red-600 bg-red-50 rounded-lg px-3 py-2">{error}</p>
      )}

      {loading ? (
        <p className="text-xs text-gray-400 text-center py-3">Loading photos...</p>
      ) : photos.length === 0 ? (
        <p className="text-xs text-gray-400 text-center py-2">
          No photos yet / ఇంకా ఫోటోలు లేవు
        </p>
      ) : (
        <div className="grid grid-cols-3 gap-1.5">
          {photos.map((p) => (
            <div
              key={p.id}
              className="aspect-square rounded-lg overflow-hidden border border-gray-100 bg-gray-50"
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={p.url}
                alt={p.caption ?? ''}
                className="w-full h-full object-cover"
              />
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

/* ─── Loading screen ────────────────────────────────────────── */
function LoadingScreen() {
  return (
    <main className="min-h-screen bg-gray-50 flex items-center justify-center">
      <div className="text-center space-y-3">
        <div className="w-12 h-12 border-4 border-green-700 border-t-transparent rounded-full animate-spin mx-auto" />
        <p className="text-gray-500 text-sm">Loading dashboard... / లోడ్ అవుతోంది...</p>
      </div>
    </main>
  )
}

/* ─── Farmer not found ──────────────────────────────────────── */
function FarmerNotFound({ onLogout }: { onLogout: () => void }) {
  return (
    <main className="min-h-screen bg-gray-50 flex flex-col items-center justify-center px-4">
      <div className="text-center max-w-sm space-y-4">
        <div className="text-6xl">🌾</div>
        <h2 className="text-xl font-extrabold text-gray-900">Session expired / సెషన్ ముగిసింది</h2>
        <p className="text-gray-500 text-sm">
          Please log in again with your WhatsApp number.<br />
          మీ వాట్సాప్ నంబర్‌తో మళ్ళీ లాగిన్ అవ్వండి.
        </p>
        <button onClick={onLogout} className="bg-green-700 text-white font-bold px-6 py-3 rounded-xl text-sm">
          Log in again / మళ్ళీ లాగిన్
        </button>
      </div>
    </main>
  )
}

