  const path = `${farmerId}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`
  const { error: upErr } = await supabase.storage
    .from('farm-images')
    .upload(path, file, { contentType: file.type, upsert: false })
  if (upErr) {
    setError(`Image upload failed: ${upErr.message}`)
    return null
  }
  const { data } = supabase.storage.from('farm-images').getPublicUrl(path)
  return data.publicUrl
}

const handleSubmit = async () => {
  if (!name.trim()) return
  setLoading(true)
  setError('')

  let imageUrl: string | null = null
  if (imageFile) {
    imageUrl = await uploadImage(imageFile)
    if (!imageUrl) { setLoading(false); return }
  }

  const payload: Record<string, unknown> = {
    farmer_id: farmerId,
    name: name.trim(),
    emoji,
    status,
    method: 'Natural',
  }
  if (variety.trim()) payload.variety = variety.trim()
  if (price) payload.price_tier_1_price = Number(price)
  if (stock) payload.stock_qty = Number(stock)
  if (imageUrl) payload.image_url = imageUrl

  const { data, error: insertError } = await supabase.from('produce_listings').insert(payload).select().single()
  setLoading(false)
  if (!insertError && data) {
    onAdded(data as Produce)
    setSuccess(true)
    setTimeout(() => { reset(); setOpen(false) }, 1500)
  } else {
    setError(insertError?.message ?? 'Failed to add produce. Check Supabase RLS policies.')
  }
}

