/* ─── Farm images card ──────────────────────────────────────── */
type MediaPhoto = { id: string; url: string; caption?: string | null }

function FarmImagesCard({ farmerId }: { farmerId: string }) {
  const [photos, setPhotos] = useState<MediaPhoto[]>([])
  const [loading, setLoading] = useState(true)
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState('')
  const [preview, setPreview] = useState<string | null>(null)
  const [pendingFile, setPendingFile] = useState<File | null>(null)
  const [caption, setCaption] = useState('')

  const loadPhotos = useCallback(async () => {
    setLoading(true)
    const { data } = await supabase
      .from('media')
      .select('id, url, caption')
      .eq('farmer_id', farmerId)
      .eq('type', 'photo')
      .order('sort_order', { ascending: true })
    setPhotos((data ?? []) as MediaPhoto[])
    setLoading(false)
  }, [farmerId])

  useEffect(() => { loadPhotos() }, [loadPhotos])

  const handleFile = (file: File | null) => {
    setError('')
    if (!file) return
    if (!file.type.startsWith('image/')) {
      setError('Please pick an image file / చిత్రం ఫైల్ ఎంచుకోండి')
      return
    }
    if (file.size > 8 * 1024 * 1024) {
      setError('Image is too large (max 8 MB) / చిత్రం 8 MB కంటే ఎక్కువ')
      return
    }
    setPendingFile(file)
    const reader = new FileReader()
    reader.onload = (e) => setPreview(e.target?.result as string)
    reader.readAsDataURL(file)
  }

  const handleUpload = async () => {
    if (!pendingFile) return
    setUploading(true)
    setError('')
    try {
      const ext = pendingFile.name.split('.').pop()?.toLowerCase() || 'jpg'
      const path = `${farmerId}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`
      const { error: upErr } = await supabase.storage
        .from('farm-images')
        .upload(path, pendingFile, {
          cacheControl: '3600',
          contentType: pendingFile.type,
          upsert: false,
        })
      if (upErr) throw upErr

      const { data: pub } = supabase.storage.from('farm-images').getPublicUrl(path)
      const publicUrl = pub.publicUrl

      const { error: insErr } = await supabase.from('media').insert({
        farmer_id: farmerId,
        type: 'photo',
        url: publicUrl,
        caption: caption.trim() || null,
        sort_order: photos.length,
      })
      if (insErr) throw insErr

      setPreview(null)
      setPendingFile(null)
      setCaption('')
      await loadPhotos()
    } catch (e) {
      const msg = e instanceof Error ? e.message : 'Upload failed'
      setError(msg)
    } finally {
      setUploading(false)
    }
  }

  const handleCancel = () => {
    setPreview(null)
    setPendingFile(null)
    setCaption('')
    setError('')
  }

  return (
    <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-3">
